28	// 资源预留表：兼具静态原子锁与时空预约区间锁（Time-Space Reservation）
29	class ResourceTable {
30	 public:
31	  struct ReserveResult {
32	    bool success = false;
33	    std::string message;
34	    std::vector<std::string> newly_reserved;  // 失败时已全部回滚，保持原子性
35	  };
36	
37	  struct ReleaseResult {
38	    bool released = false;
39	    std::string message;
40	  };
41	
42	  // 原子静态排他预留：任一资源被他人持有则整体失败且不落锁。
43	  ReserveResult Reserve(const std::string& mission_id,
44	                        const std::vector<std::string>& resource_ids);
45	
46	  // 时空窗口预约：允许多车错峰占用同一路段，只要时间窗口不重叠即可并行预约！
47	  bool ReserveTimeSpace(const std::string& mission_id,
48	                        const std::string& resource_id,
49	                        std::chrono::steady_clock::time_point start,
50	                        std::chrono::steady_clock::time_point end,
51	                        std::string* message);
52	
53	  // 释放某任务持有的全部资源（含时空预约），返回是否实际删除。
54	  ReleaseResult Release(const std::string& mission_id);
55	
56	  // 逐段动态解锁：仅释放 owner == mission_id 且列于 resource_ids 的锁。
